import json
from pathlib import Path
from sympy import symbols, SOPform, And, Or, Not

spec = TASK["public"]["specification"]
xs = symbols("x0:10")
mins = [tuple(row) for row, y in zip(spec["inputs"], spec["outputs"]) if y]
expr = SOPform(xs, mins)
terms = list(expr.args) if expr.func is Or else [expr]

ops = []
def setv(tensor, index, value):
    if value:
        ops.append({"op": "set", "tensor": tensor, "index": list(index), "value": float(value)})

# Layer 0: retain inputs and compute each conjunction term as a threshold.
for i in range(10):
    setv("w0", (i, i), 1)
for j, term in enumerate(terms):
    lits = list(term.args) if term.func is And else [term]
    positives, negatives = [], []
    for lit in lits:
        if lit.func is Not:
            negatives.append(int(str(lit.args[0])[1:]))
        else:
            positives.append(int(str(lit)[1:]))
    row = 10 + j
    for i in positives:
        setv("w0", (row, i), 1)
    for i in negatives:
        setv("w0", (row, i), -1)
    setv("b0", (row,), 1 - len(positives))

# Layer 1: OR the term indicators; retain input channels.
for i in range(10):
    setv("w1", (i, i), 1)
for j in range(len(terms)):
    setv("w1", (17, 10 + j), 1)
setv("b1", (17,), -0.5)

# Carry the OR signal through the remaining ReLU stages.
for layer in (2, 3):
    for i in range(10):
        setv(f"w{layer}", (i, i), 1)
    setv(f"w{layer}", (17, 17), 1)

# Class 1 wins iff the Boolean output is true; class 0 wins the false tie.
setv("out", (1, 17), 1)
setv("bias", (2,), -1)

sub = {"patch": ops}
check_submission(sub)
Path("/work/submission.json").write_text(json.dumps(sub))
